export function getBuiltInSfxCatalog(lang: 'en' | 'it'): SfxItem[] {
  return SFX_DEFINITIONS.map((def) => ({
    ...def,
    name: def.name[lang],
    description: def.description[lang],
    tags: [...def.tags],
  }));
}
